96	    fn next(&mut self) -> Option<Self::Item> {
97	        // Collapse \r\n into \n
98	        if let Some((i, '\r')) = self.chr0 {
99	            if let Some((_, '\n')) = self.chr1 {
100	                // Transform windows EOL into \n
101	                let _ = self.shift();
102	                // using the position from the \r
103	                self.chr0 = Some((i, '\n'))
104	            } else {
105	                // Transform MAC EOL into \n
106	                self.chr0 = Some((i, '\n'))
107	            }
108	        }
109	
110	        self.shift()
111	    }
